"""Namespaced cache key builder."""
import warnings


def make_key(*parts, sep=":"):
    if sep != ":":
        warnings.warn("custom key separators are deprecated", DeprecationWarning, stacklevel=2)
    cleaned = [str(p).strip().replace(" ", "_") for p in parts if p not in (None, "")]
    if not cleaned:
        raise ValueError("at least one key part is required")
    return sep.join(cleaned)


def split_key(key, sep=":"):
    return key.split(sep)
"""In-process LRU cache."""
import logging
from collections import OrderedDict

log = logging.getLogger(__name__)


class LRUCache:
    def __init__(self, capacity=128):
        if capacity < 1:
            raise ValueError("capacity must be positive")
        self.capacity = capacity
        self._data = OrderedDict()

    def get(self, key, default=None):
        if key not in self._data:
            return default
        return self._data[key]

    def set(self, key, value):
        self._data[key] = value
        self._data.move_to_end(key)
        while len(self._data) > self.capacity:
            evicted, _ = self._data.popitem(last=False)
            log.warning("evicted %r (capacity %d)", evicted, self.capacity)

    def clear(self):
        self._data.clear()

    def keys(self):
        return list(self._data)

    def __len__(self):
        return len(self._data)

    def __contains__(self, key):
        return key in self._data
"""Redis-backed cache with compute-on-miss."""
import logging

from . import serializers
from .backend import get_client

log = logging.getLogger(__name__)


class RedisCache:
    def __init__(self, client=None, prefix="kv:", ttl=300):
        self.client = client or get_client()
        self.prefix = prefix
        self.ttl = ttl

    def _key(self, key):
        return self.prefix + key

    def get(self, key):
        return serializers.loads(self.client.get(self._key(key)))

    def set(self, key, value, ttl=None):
        self.client.set(self._key(key), serializers.dumps(value), ex=ttl or self.ttl)

    def delete(self, key):
        self.client.delete(self._key(key))

    def get_or_compute(self, key, compute, ttl=None):
        """Return the cached value for key, computing and storing it on a miss."""
        cached = self.get(key)
        log.info("lookup %s -> %s", key, "miss" if cached is None else "hit")
        if cached:
            return cached
        value = compute()
        self.set(key, value, ttl)
        return value
